*** Add File: script.js
+const form = document.querySelector("#support-form");
+const statusMessage = document.querySelector("#form-status");
+const requiredFields = Array.from(form.querySelectorAll("[required]"));
+
+function setInvalidState(field, isInvalid) {
+  if (isInvalid) {
+    field.setAttribute("aria-invalid", "true");
+    return;
+  }
+
+  field.removeAttribute("aria-invalid");
+}
+
+function validateField(field) {
+  const isInvalid = !field.validity.valid;
+  setInvalidState(field, isInvalid);
+  return !isInvalid;
+}
+
+requiredFields.forEach((field) => {
+  field.addEventListener("input", () => {
+    validateField(field);
+
+    if (requiredFields.every((requiredField) => requiredField.validity.valid)) {
+      statusMessage.textContent = "";
+      statusMessage.classList.remove("error");
+    }
+  });
+});
+
+form.addEventListener("submit", (event) => {
+  event.preventDefault();
+
+  const firstInvalidField = requiredFields.find((field) => !validateField(field));
+
+  if (firstInvalidField) {
+    statusMessage.textContent =
+      "Please complete the required fields before submitting.";
+    statusMessage.classList.add("error");
+    firstInvalidField.focus();
+    return;
+  }
+
+  form.reset();
+  requiredFields.forEach((field) => setInvalidState(field, false));
+  statusMessage.textContent = "Thanks. Your support request has been submitted.";
+  statusMessage.classList.remove("error");
+});
*** End Patch
